-- Mora de 1.4.02 al 30-sep-2025: cuotas con devengo (5) menos reverso (6), condonado (9) y mora cobrada desde el ancla NEGATIVO, desglosadas.
-- Respuesta al árbitro sobre el tope por cuota o por préstamo (lote 7, D-186). Solo SELECT.
WITH dv AS (SELECT DTPRCDGO, SUM(CASE MVICTPMV WHEN 5 THEN MVICVLOR ELSE 0 END) t5, SUM(CASE MVICTPMV WHEN 6 THEN MVICVLOR ELSE 0 END) t6, SUM(CASE MVICTPMV WHEN 9 THEN MVICVLOR ELSE 0 END) t9
            FROM CRD.MVIC WHERE MVICCMPN=2 AND MVICTPMV IN (5,6,9) AND NVL(MVICANUL,0)=0 AND MVICFCCT <= DATE '2025-09-30' GROUP BY DTPRCDGO),
pg AS (SELECT DTPRCDGO, SUM(NVL(PGPRMRPG,0)) mp FROM CRD.PGPR WHERE NVL(PGPRANUL,0)=0 AND PGPRFCHA >= DATE '2025-06-01' AND PGPRFCHA < DATE '2025-10-01' AND NVL(PGPRMRPG,0)>0 GROUP BY DTPRCDGO),
x AS (SELECT NVL(dv.DTPRCDGO,pg.DTPRCDGO) cuota, NVL(t5,0) t5, NVL(t6,0) t6, NVL(t9,0) t9, NVL(mp,0) mp FROM dv FULL JOIN pg ON pg.DTPRCDGO=dv.DTPRCDGO)
SELECT COUNT(*) cuotas, ROUND(SUM(t5),2) devengo5, ROUND(SUM(t6),2) reverso6, ROUND(SUM(t9),2) condonado9, ROUND(SUM(mp),2) cobrada, ROUND(SUM(t5-t6-t9-mp),2) neto
FROM x WHERE t5-t6-t9-mp < -0.005;
